"use strict";(globalThis.webpackChunkdocumentation||=[]).push([[3664],{26651(e,t,n){n.r(t),n.d(t,{assets:()=>h,contentTitle:()=>r,default:()=>c,frontMatter:()=>a,metadata:()=>s,toc:()=>d});const s=JSON.parse('{"id":"server-admin/admin-tips/blocking-on-bad-requests","title":"Blocking ERDDAP\u2122 requests based on the content of the request, not based on the IP","description":"This content is based on a message from Roy Mendelssohn to the ERDDAP\u2122 users group.","source":"@site/docs/server-admin/admin-tips/blocking-on-bad-requests.md","sourceDirName":"server-admin/admin-tips","slug":"/server-admin/admin-tips/blocking-on-bad-requests","permalink":"/pl/docs/server-admin/admin-tips/blocking-on-bad-requests","draft":false,"unlisted":false,"editUrl":"https://github.com/erddap/erddap.github.io/tree/main/docs/server-admin/admin-tips/blocking-on-bad-requests.md","tags":[],"version":"current","frontMatter":{},"sidebar":"docSidebar","previous":{"title":"Admin Porady","permalink":"/pl/docs/category/admin-tips"},"next":{"title":"How to Deploy ERDDAP\u2122 on Kubernetes","permalink":"/pl/docs/server-admin/admin-tips/deploy-kubernetes"}}');var i=n(74848),o=n(28453);const a={},r="Blocking ERDDAP\u2122 requests based on the content of the request, not based on the IP",h={},d=[{value:"The problem",id:"the-problem",level:2},{value:"Solution",id:"solution",level:2},{value:"Explanation",id:"explanation",level:2}];function l(e){const t={a:"a",code:"code",h1:"h1",h2:"h2",header:"header",li:"li",p:"p",pre:"pre",ul:"ul",...(0,o.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(t.header,{children:(0,i.jsx)(t.h1,{id:"blocking-erddap-requests-based-on-the-content-of-the-request-not-based-on-the-ip",children:"Blocking ERDDAP\u2122 requests based on the content of the request, not based on the IP"})}),"\n",(0,i.jsxs)(t.p,{children:["This content is based on a ",(0,i.jsx)(t.a,{href:"https://groups.google.com/g/erddap/c/XcvPkoGtchg",children:"message from Roy Mendelssohn to the ERDDAP\u2122 users group"}),"."]}),"\n",(0,i.jsx)(t.h2,{id:"the-problem",children:"The problem"}),"\n",(0,i.jsx)(t.p,{children:"If you are like us,  you are seeing a lot of bots making data requests to your ERDDAP\u2122,  and the requests often seem like they are done by poorly coded scripts,  whether by LLMs (my guess) or by humans.  One thing about LLMs is they will do exactly what you prompt them to do,  so if you don\u2019t tell them to have the script check return codes, and don\u2019t  tell them what to do in different cases,  then usually the code will not do either of those things.  And if you tell it to keep on trying,  it will.  Which is what we are seeing at least."}),"\n",(0,i.jsx)(t.p,{children:"But the ones that are doing a number on our ERDDAP\u2122 are like this:"}),"\n",(0,i.jsx)(t.p,{children:(0,i.jsx)(t.a,{href:"https://coastwatch.pfeg.noaa.gov/erddap/jplMURSST41.parquetWMeta",children:"https://coastwatch.pfeg.noaa.gov/erddap/jplMURSST41.parquetWMeta"})}),"\n",(0,i.jsx)(t.p,{children:"These send ERDDAP\u2122 into never-never land, due,  to the best that I can determine,  that this URL is not only requesting the entire dataset,  which is I don\u2019t know how many terabytes,  but wants it converted to a parquet file.  Worse the requests are coming in from moving IPs,  so blocking IPs is worse than whack-a-mole,  you will never get them all blocked."}),"\n",(0,i.jsx)(t.p,{children:"So the question is how can you block based on the content of the request?  Before going further,  if you are experience crashes it may be from different causes then what we are seeing - I spent a lot of time going through logs and also I get notified when there is dangerous high memory use,  and noted when a crash followed that notification,  and also noticed what was the common denominator in these crashes,  which may not be the case for your server.  So research this before taking any action,  but this may  give you some idea how to block these requests."}),"\n",(0,i.jsx)(t.p,{children:"Just so I am clear,  you can think of an ERDDAP\u2122 request as:"}),"\n",(0,i.jsx)(t.p,{children:(0,i.jsx)(t.a,{href:"https://baseURL/erddap/method/datasetID.filetype?constraint",children:"https://baseURL/erddap/method/datasetID.filetype?constraint"})}),"\n",(0,i.jsx)(t.p,{children:"In our case the common denominator of the crashes were griddap or tabletop requests with certain filetypes but no constraint.  So the question is how to block requests without a constraint?  Except it is not  that simple,  because there are any number of filetypes that don\u2019t need a constraint and will be well-behaved, so we don\u2019t want to block those.  After talking to Chris,  and no doubt I have left out something,  the filetypes that are well behaved without a constraint are:"}),"\n",(0,i.jsxs)(t.ul,{children:["\n",(0,i.jsx)(t.li,{children:".croissant"}),"\n",(0,i.jsx)(t.li,{children:".iso19115_2"}),"\n",(0,i.jsx)(t.li,{children:".iso19139_2007"}),"\n",(0,i.jsx)(t.li,{children:".iso19115_3_2016"}),"\n",(0,i.jsx)(t.li,{children:".ncCFHeader"}),"\n",(0,i.jsx)(t.li,{children:".ncCFMAHeader"}),"\n",(0,i.jsx)(t.li,{children:".das"}),"\n",(0,i.jsx)(t.li,{children:".dds"}),"\n",(0,i.jsx)(t.li,{children:".html"}),"\n",(0,i.jsx)(t.li,{children:".graph"}),"\n",(0,i.jsx)(t.li,{children:".subset"}),"\n",(0,i.jsx)(t.li,{children:".ncHeader"}),"\n",(0,i.jsx)(t.li,{children:".help"}),"\n",(0,i.jsx)(t.li,{children:".fgdc"}),"\n",(0,i.jsx)(t.li,{children:".iso19115"}),"\n",(0,i.jsx)(t.li,{children:".ncoJsonHeader (this one will be in the upcoming new release)."}),"\n"]}),"\n",(0,i.jsx)(t.h2,{id:"solution",children:"Solution"}),"\n",(0,i.jsx)(t.p,{children:'The solution "I found" works in Apache2,  I do not know nginx but I imagine there is something similar.  At first I tried mod_security,  but that got too complicated and didn\u2019t work very well.  The solution is to use mod_rewrite.  Now I am anything but an expert on this, so while I defined what I was trying to accomplish,  the solution, as well as the explanation,  is due to Claude.ai.  ChatGPT will supply you with basically the same answer.'}),"\n",(0,i.jsx)(t.p,{children:"Step 1.  Make certain that mod_rewrite is installed and enabled.  Since how to do this varies with OS,  this is something you can ask your favorite chatbot."}),"\n",(0,i.jsx)(t.p,{children:"Step 2.  In the appropriate file that configures ssl for apache2 (which again varies by OS), for example it might be something like /etc/apache2/sites-enabled/ssl.conf,  add the following under the appropriate VirtualHost definition (note if you copy this there are only 4 lines,  the third line may be wrapped,  unwrap it)"}),"\n",(0,i.jsx)(t.pre,{children:(0,i.jsx)(t.code,{children:"RewriteEngine On\nRewriteCond %{QUERY_STRING} ^$\nRewriteCond %{REQUEST_URI} ^/erddap/(griddap|tabledap)/[^/?]+\\.(?!(?:croissant|iso19115_2|iso19139_2007|iso19115_3_2016|ncCFHeader|ncCFMAHeader|das|dds|html|graph|subset|ncHeader|help|fgdc|iso19115|ncoJsonHeader)$)[A-Za-z0-9_]+$\nRewriteRule ^ - [R=429,L]\n"})}),"\n",(0,i.jsxs)(t.p,{children:["Step 3.  Check that the configuration is valid:  ",(0,i.jsx)(t.code,{children:"sudo apache2ctl configtest"})]}),"\n",(0,i.jsxs)(t.p,{children:["Step 4.  Restart apache2:  ",(0,i.jsx)(t.code,{children:"sudo systemctl restart apache2"})]}),"\n",(0,i.jsx)(t.p,{children:"Step 5.  Check your logs that nothing is being blocked that should not be,  and that appropriate requests without a constraint return a 429 without ever hitting your tomcat"}),"\n",(0,i.jsx)(t.h2,{id:"explanation",children:"Explanation"}),"\n",(0,i.jsx)(t.p,{children:"Why does this work and what does this do - here is the explanation from Claude.ai:"}),"\n",(0,i.jsxs)(t.p,{children:["Line 1 \u2014 ",(0,i.jsx)(t.code,{children:"RewriteEngine On"}),"\nTurns on mod_rewrite processing for this scope. Without it, the RewriteCond/RewriteRule directives below are simply ignored."]}),"\n",(0,i.jsxs)(t.p,{children:["Line 2 \u2014 ",(0,i.jsx)(t.code,{children:"RewriteCond %{QUERY_STRING} ^$"}),"\nA condition that must be true before the rule below applies. ",(0,i.jsx)(t.code,{children:"%{QUERY_STRING}"}),' is everything after the ? in the request URL. ^$ is a regex meaning "start of string immediately followed by end of string" \u2014 i.e., an empty string. So this condition is true only when there\'s no query string at all \u2014 no subsetting/constraint expression on the request.']}),"\n",(0,i.jsxs)(t.p,{children:["Line 3 \u2014 ",(0,i.jsx)(t.code,{children:"RewriteCond %{REQUEST_URI} ^/erddap/(griddap|tabledap)/[^/?]+\\.(?!(?:...)$)[A-Za-z0-9_]+$"}),"\nA second condition, checked against ",(0,i.jsx)(t.code,{children:"%{REQUEST_URI}"})," \u2014 the literal request path as the client sent it, always the full path regardless of where in the config this rule lives (deliberately chosen over letting the RewriteRule pattern itself do the matching, because pattern-matching inside a ",(0,i.jsx)(t.code,{children:"<Location>"})," block can behave ambiguously \u2014 see note below). Breaking down the regex:"]}),"\n",(0,i.jsxs)(t.p,{children:[(0,i.jsx)(t.code,{children:"^/erddap/"})," \u2014 must start with /erddap/\n(griddap|tabledap)/ \u2014 followed by one of the two ERDDAP\u2122 access methods"]}),"\n",(0,i.jsxs)(t.p,{children:[(0,i.jsx)(t.code,{children:"[^/?]+"})," \u2014 the datasetID: one or more characters that aren't / or ?"]}),"\n",(0,i.jsxs)(t.p,{children:[(0,i.jsx)(t.code,{children:"\\."})," \u2014 a literal dot"]}),"\n",(0,i.jsxs)(t.p,{children:[(0,i.jsx)(t.code,{children:"(?!(?:croissant|iso19115_2|...|ncoJsonHeader)$)"}),' \u2014 a negative lookahead: "as long as what follows is not one of these exact fileType names all the way to the end of the string." These are the fileTypes ERDDAP\u2122 can legitimately serve with no constraint (metadata, structure, form pages, etc.) \u2014 the lookahead is what excludes them from being blocked.']}),"\n",(0,i.jsxs)(t.p,{children:[(0,i.jsx)(t.code,{children:"[A-Za-z0-9_]+$"})," \u2014 the actual fileType extension (letters, digits, underscore), required to run to the end of the string.\nSo this condition is true only when the path is a griddap/tabledap request for some fileType that isn't on the safe-without-constraint list."]}),"\n",(0,i.jsxs)(t.p,{children:["Line 4 \u2014 ",(0,i.jsx)(t.code,{children:"RewriteRule ^ - [R=429,L]"}),'\nThe rule itself. Because both conditions above must already be true for Apache to even evaluate this line, the pattern here doesn\'t need to check anything else \u2014 ^ just matches "start of the string," which is always true. - means "don\'t rewrite the URL to anything different" (we\'re not redirecting anywhere, just short-circuiting the request). The flags:']}),"\n",(0,i.jsxs)(t.p,{children:[(0,i.jsx)(t.code,{children:"R=429"}),' \u2014 respond with an HTTP redirect-class action carrying status code 429 ("Too Many Requests") instead of serving the request.\nL \u2014 "Last": stop processing any further rewrite rules once this one fires.\nPut together: if the query string is empty, AND the request is for a griddap/tabledap fileType that isn\'t on the safe-unconstrained list, immediately return 429 \u2014 without ever contacting the ERDDAP/Tomcat backend.']}),"\n",(0,i.jsxs)(t.p,{children:["Why ",(0,i.jsx)(t.code,{children:"%{REQUEST_URI}"})," instead of letting the RewriteRule pattern match the path directly (worth including as a note for colleagues, since it's the non-obvious part): inside a ",(0,i.jsx)(t.code,{children:"<Location>"})," block, what a bare RewriteRule pattern actually gets matched against can behave inconsistently depending on Apache version and context. Explicitly pulling the full path via RewriteCond ",(0,i.jsx)(t.code,{children:"%{REQUEST_URI}"})," sidesteps that ambiguity entirely \u2014 it's always the literal, complete request path, so the regex behaves exactly as written regardless of where the rule is nested."]}),"\n",(0,i.jsx)(t.p,{children:"I have been using this for several days now and it appears to work very well,  it is blocking what I am trying to block and not blocking what I don\u2019t want to block.  And our ERDDAP\u2122 has become much more stable."})]})}function c(e={}){const{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(l,{...e})}):l(e)}},28453(e,t,n){n.d(t,{R:()=>a,x:()=>r});var s=n(96540);const i={},o=s.createContext(i);function a(e){const t=s.useContext(o);return s.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:a(e.components),s.createElement(o.Provider,{value:t},e.children)}}}]);